        cout << "the point is on bounded side" << endl;
        break;
    case CGAL::ON_BOUNDARY:
        cout << "the point is on the boundary" << endl;
        break;
    case CGAL::ON_UNBOUNDED_SIDE:
        cout << "the point is on the unbounded side" << endl;
        break;
