    if (polygon.size() < 3) return false;

    int n = polygon.size();
    bool positive = false;
    bool negative = false;

    for (int i = 0; i < n; ++i) {
        const Point_2& p1 = polygon[i];
        const Point_2& p2 = polygon[(i + 1) % n];
        const Point_2& p3 = polygon[(i + 2) % n];

        K::Orientation_2 orientation;
        CGAL::Orientation orient = orientation(p1, p2, p3);

        if (orient == CGAL::COLLINEAR) continue;

        if (orient == CGAL::LEFT_TURN) {
            positive = true;
        } else if (orient == CGAL::RIGHT_TURN) {
            negative = true;
